var I18N_Q = {"QUOTES": [["story", "Ahmed Zewail was born in Damanhour, grew up in Desouq and studied at Alexandria University. He kept going until he won the Nobel Prize in Chemistry in 1999. Starting at an ordinary public school didn't stop him.", "Ahmed Zewail"], ["story", "Taha Hussein lost his sight as a child, yet became the “Dean of Arabic Literature” and Minister of Education. He said education must be a right for everyone, like water and air.", "Taha Hussein"], ["story", "Egyptian heart surgeon Magdi Yacoub performed thousands of operations around the world, then came back to build the Aswan Heart Centre. Mastery starts with daily repetition.", "Magdi Yacoub"], ["story", "Naguib Mahfouz worked a day job and wrote every day at fixed hours, without waiting for the mood. That discipline took him to the Nobel Prize in Literature in 1988.", "Naguib Mahfouz"], ["story", "As a boy, Mohamed Salah travelled for hours every day from Nagrig to train in Cairo. That long road is what made the player.", "Mohamed Salah"], ["story", "Sameera Moussa was one of Egypt's first women nuclear scientists. Her father moved the family to Cairo so she could continue her education, and she didn't let him down.", "Sameera Moussa"], ["story", "Michael Jordan didn't make his school's varsity team one year. He went home and cried, then trained harder than anyone and became one of the greatest basketball players ever.", "Michael Jordan"], ["story", "J. K. Rowling's “Harry Potter” was rejected by many publishers before one accepted it. If she had quit after the first rejection, no one would know her name.", "J. K. Rowling"], ["story", "Marie Curie worked in a simple lab with few resources, and became the first person to win Nobel Prizes in two different sciences: physics and chemistry.", "Marie Curie"], ["story", "Ibn al-Haytham wrote the “Book of Optics” on light and vision while living in Cairo, and he is seen as one of the first to rely on experiment in science.", "Ibn al-Haytham"], ["story", "Mostafa Mosharafa was among the top students in the country, and became a physics professor and dean of the Faculty of Science while still young. He said science must reach people.", "Mostafa Mosharafa"], ["story", "Thomas Edison tried a huge number of materials before finding one that worked for the light bulb. Every failed try brought him closer.", "Thomas Edison"], ["proverb", "Whoever works hard finds; whoever plants, harvests.", ""], ["proverb", "Learning when young is like carving in stone.", ""], ["proverb", "Time is like a sword: if you don't cut it, it cuts you.", ""], ["proverb", "Drop by drop makes a river.", ""], ["proverb", "Patience pays off.", ""], ["proverb", "When your winds blow, make the most of them.", ""], ["proverb", "No right is lost while someone keeps asking for it.", ""], ["proverb", "The first rain begins with a single drop.", ""], ["proverb", "What's past is past; we are children of today.", ""], ["proverb", "Luck won't save you every time, so study as you go.", ""], ["poetry", "Resolve comes in the measure of the resolute, and noble deeds in the measure of the noble.", "Al-Mutanabbi"], ["poetry", "Goals are not reached by wishing; the world is won by striving.", "Ahmed Shawqi"], ["poetry", "Whoever never tastes the bitterness of learning for an hour will swallow the humiliation of ignorance all his life.", "Attributed to Imam al-Shafi'i"], ["poetry", "If you venture for a lofty honour, don't settle for anything below the stars.", "Al-Mutanabbi"], ["line", "You don't have to be 100% ready to start. Start, and the readiness comes along the way.", ""], ["line", "A small step every day beats a big step every month.", ""], ["line", "The lesson you study today is a mark in tomorrow's exam.", ""], ["line", "Review isn't wasted time; it's what keeps what you studied in your head.", ""], ["line", "Don't compare yourself to anyone. Compare yourself to yesterday's {N}.", ""], ["line", "Tiredness fades; success stays.", ""], ["line", "25 focused minutes without your phone beat two distracted hours.", ""], ["line", "If a lesson is hard, break it down. Any mountain is climbed step by step.", ""], ["line", "Mistakes in practice are a gain: they show you where you stand before the exam.", ""], ["line", "Going to school is part of your success. Don't let it slip.", ""], ["line", "You don't need to be the best. You need to be better than yesterday.", ""], ["line", "Write down the question you don't understand and ask about it. Asking is no shame.", ""], ["line", "Every ✔ here means you're closer to your goal.", ""], ["line", "Good sleep is part of studying, not against it.", ""], ["line", "Whoever walks slowly but never stops arrives.", ""], ["line", "Whenever you feel like quitting, remember why you started.", ""], ["line", "A bad day doesn't mean a bad week. Come back tomorrow.", ""], ["line", "Understanding a lesson matters more than memorising it, and practice locks the understanding in.", ""], ["line", "What you studied won't be lost. Even if you feel you forgot, review brings it back fast.", ""], ["word", "We're proud of you, {N} 💜", "Ahmed"], ["word", "You're stronger than any exam.", ""], ["word", "Keep going; the result is coming.", ""], ["word", "Every day you study is a win.", ""], ["word", "Believe in yourself. You can do it.", ""], ["word", "Smile and start 😊", ""], ["English", "Small steps every day lead to big results.", ""], ["English", "Don't wish for it. Work for it.", ""], ["English", "Success is the sum of small efforts, repeated day in and day out.", "Robert Collier"], ["English", "It always seems impossible until it's done.", "Nelson Mandela"], ["English", "The expert in anything was once a beginner.", ""], ["English", "Believe you can and you're halfway there.", "Theodore Roosevelt"], ["English", "Done is better than perfect.", ""], ["English", "Your future is created by what you do today, not tomorrow.", ""], ["English", "Mistakes are proof that you are trying.", ""], ["English", "Focus on progress, not perfection.", ""]], "TAGS": {"story": "📜 Inspiring story", "proverb": "🗣️ Proverb", "poetry": "✒️ Poetry", "line": "💬 Today's line", "word": "💜 A word for you", "English": "🇬🇧 English quote"}, "KIDQ": ["Every lesson you finish earns you new stars ⭐", "You're doing great, {N}, and every day you learn something new 🌱", "A small step every day takes you all the way up the ladder 🪜", "Mistakes aren't shameful. Mistakes teach us 💡", "Fifteen minutes of focus, then play as much as you like 🎈", "Read out loud: your ears study with you too 🎧", "If the lesson is hard, take a deep breath and start again 🌬️", "Asking the teacher is smart, not embarrassing 🙋", "Pack your bag at night, and the morning gets easier 🎒", "Sleeping early keeps your brain awake in class 😴", "Every letter you write by hand stays in your head ✍️", "Drink water and eat breakfast before school 🥪", "Review makes the lesson your friend ✨", "Today is better than yesterday, and tomorrow will be even better 🌈", "Help a friend with a lesson and you'll understand it better too 🤝", "{N}, the stars are waiting for you today! 🌟"], "PTIPS": ["Fifteen minutes of study every day beats two hours only on the weekend ⏱️", "Praise the effort, not just the grade. “You studied well today” matters more than “What did you get?” 💛", "A fixed study spot, no TV, and the phone for the app only 📵", "Ask {N}: “What's the best thing you learned today?” instead of “Did you study?” 🗣️", "Sleeping early is part of studying. A late sleeper can't focus 😴", "If a lesson is hard, break it into small pieces: listen, then understand, then practise ✂️", "Let {N} tick the step themselves. The feeling of doing it alone makes a difference 👆", "Compare {N} with yesterday's self, not with classmates 📈", "Mistakes are a chance. Write the missed question in the “Mistakes notebook” and come back to it in a few days 📝", "Send the weekly report to someone else who follows {N}, so the follow-up is shared 📤", "Every fifteen minutes of focus deserves a 5-minute break 🎈", "Assessment day isn't a day to fear. Calm review a week before beats a last-night cram 📆", "Reading out loud with {N} a little every day helps with Arabic 📖", "If you notice something isn't understood, talk to the teacher early. Early fixes are easier 🏫", "Celebrate the star {N} earns in the app together 🌟", "You don't have to be a teacher. Just being next to {N} while they study makes a difference 🤍"]};
